from pwn import *

bard_path = '/home/ctfplayer/ctf_files/bard'

def bard_interaction():
    p = process(bard_path)
    log.info(p.recvuntil(b'Bard #1').decode(errors='ignore'))
    for i in range(1, 11):
        if i != 10:
            try:
                log.info(p.recvuntil(b'alignment').decode(errors='ignore'))
            except Exception:
                pass
        p.sendline(b'g')
        log.info(p.recvuntil(b'weapon').decode(errors='ignore'))
